&lt;ul&gt;
&lt;li data-leveltext=&quot;●&quot; data-font=&quot;&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;134224900&amp;quot;:false,&amp;quot;201340374&amp;quot;:0,&amp;quot;335551500&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;●&amp;quot;}&quot; data-aria-posinset=&quot;6&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Design distributed workflows that operate correctly under eventual consistency, at-least-once delivery, concurrent writes and partial failure, with idempotency and safe recovery as fundamental properties.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559991&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
